import React, { Component } from 'react';
import { URL } from "../URLConstant";
var Loader = require("react-loader")

export default class CallbackHandler extends Component {

    constructor(props) {
        super(props);
        this.state = {
            data: "",

        }
    }


    componentDidMount() {
        const urlParams = new URLSearchParams(window.location.search);
        const result = urlParams.get('result');
        console.log("Result from APK:"+ result);
        this.setState({data:result});
        // Handle the result as needed, e.g., store it, display a message, etc.

        
    }

    render() {
        return (
            // <div>
            //     <h1>Callback Received</h1>
            //     <p>Processing the response from APK...</p>
            // </div>

            <div className="success-container">
                <Loader loaded={this.state.loaded}
                    lines={13} radius={20}
                    corners={1} rotate={0} direction={1} color="#000" speed={1}
                    trail={60} shadow={false} hwaccel={false} className="spinner loader"
                    zIndex={2e9} top="50%" left="50%" scale={1.00}
                    loadedClassName="loadedContent"
                />
                <iframe name="my_iframe" id="my_iframe" frameBorder="0" className="iframe" onLoad={this.onLoad.bind(this)} scrolling="yes"></iframe>
                <form id="URL" name="URL" method="POST" action={URL.reRouteNsdlResp} encType="multipart/form-data" target="my_iframe" ref="form">

                    <input type="hidden" name="obj" id="obj" value="" />
                    <input type="hidden" name="msg" id="msg" value={this.state.data} />
                </form>
            </div>


        );
    }
}